//! Read operations for macOS FUSE filesystem.
//!
//! Contains handler logic for: init, destroy, lookup, getattr, open, read,
//! release, flush, access, getxattr, listxattr.

#[cfg(feature = "fuse")]
pub(crate) mod implementation {
    use fuser::{
        consts::FOPEN_DIRECT_IO, ReplyAttr, ReplyData, ReplyEmpty, ReplyEntry, ReplyOpen,
        ReplyXattr,
    };
    use std::ffi::OsStr;
    use std::sync::atomic::Ordering;
    use std::time::{Duration, SystemTime};

    use crate::constants::CONTENT_DOWNLOAD_TIMEOUT;
    use crate::CipherBoxFS;

    const FILEPOINTER_POLL_TIMEOUT: Duration = Duration::from_secs(5);
    const FILEPOINTER_POLL_INTERVAL: Duration = Duration::from_millis(100);

    /// Poll for an in-flight async FilePointer resolution to complete.
    /// Poll result: why did we stop waiting?
    enum PollResult {
        Resolved,
        TimedOut,
        NotInFlight,
    }

    /// Poll for an in-flight async FilePointer resolution to complete.
    /// Only blocks if an async resolution task is actually in-flight for this inode.
    fn poll_filepointer_resolution(fs: &mut CipherBoxFS, ino: u64) -> PollResult {
        if !fs.resolving_file_pointers.contains(&ino) {
            log::debug!(
                "poll_filepointer_resolution: ino={} has no in-flight resolution",
                ino
            );
            return PollResult::NotInFlight;
        }
        let deadline = std::time::Instant::now() + FILEPOINTER_POLL_TIMEOUT;
        while std::time::Instant::now() < deadline {
            std::thread::sleep(FILEPOINTER_POLL_INTERVAL);
            fs.drain_filepointer_completions();
            // Break early if async task completed with Failure (ino removed from set)
            if !fs.resolving_file_pointers.contains(&ino) {
                if let Some(inode) = fs.inodes.get(ino) {
                    if let crate::inode::InodeKind::File {
                        file_meta_resolved: true,
                        cid,
                        ..
                    } = &inode.kind
                    {
                        if !cid.is_empty() {
                            return PollResult::Resolved;
                        }
                    }
                }
                log::debug!(
                    "poll_filepointer_resolution: ino={} async task finished but resolution failed",
                    ino
                );
                return PollResult::NotInFlight;
            }
            // Still in-flight — check if resolved yet
            if let Some(inode) = fs.inodes.get(ino) {
                if let crate::inode::InodeKind::File {
                    cid,
                    file_meta_resolved: true,
                    ..
                } = &inode.kind
                {
                    if !cid.is_empty() {
                        return PollResult::Resolved;
                    }
                }
            }
        }
        PollResult::TimedOut
    }
    use crate::file_handle::OpenFileHandle;
    use crate::helpers::is_platform_special;
    use crate::inode::InodeKind;
    use crate::operations::implementation::{
        current_gid, current_uid, fetch_and_decrypt_content_async, fetch_and_decrypt_file_content,
        publish_file_metadata, ttl_for_is_dir,
    };

    /// Initialize the filesystem.
    pub fn handle_init(
        fs: &mut CipherBoxFS,
        _config: &mut fuser::KernelConfig,
    ) -> Result<(), libc::c_int> {
        log::info!("CipherBoxFS::init (root pre-populated, no network I/O)");
        log::info!("Root IPNS name: {}", fs.root_ipns_name);
        log::info!("Inode count: {}", fs.inodes.inodes.len());
        Ok(())
    }

    /// Clean up all caches and zeroize sensitive data on unmount.
    pub fn handle_destroy(fs: &mut CipherBoxFS) {
        use zeroize::Zeroize;

        fs.content_cache.clear();
        fs.metadata_cache.clear();

        for (_, content) in fs.pending_content.iter_mut() {
            content.zeroize();
        }
        fs.pending_content.clear();

        for (_, handle) in fs.open_files.iter_mut() {
            if let Some(ref mut c) = handle.cached_content {
                c.zeroize();
            }
        }
        fs.open_files.clear();

        log::info!("CipherBoxFS destroyed: all caches zeroized");
    }

    /// Look up a child by name within a parent directory.
    pub fn handle_lookup(fs: &mut CipherBoxFS, parent: u64, name: &OsStr, reply: ReplyEntry) {
        fs.drain_upload_completions();
        fs.drain_refresh_completions();
        fs.drain_filepointer_completions();

        let name_str = match name.to_str() {
            Some(n) => n,
            None => {
                reply.error(libc::ENOENT);
                return;
            }
        };

        // Handle "." and ".." -- NFS clients rely on these working.
        if name_str == "." {
            if let Some(inode) = fs.inodes.get(parent) {
                reply.entry(
                    &ttl_for_is_dir(inode.attr.is_dir),
                    &inode.attr.to_fuse_attr(current_uid(), current_gid()),
                    0,
                );
                return;
            }
        }
        if name_str == ".." {
            let parent_ino = fs.inodes.get(parent).map(|i| i.parent_ino).unwrap_or(1);
            if let Some(inode) = fs.inodes.get(parent_ino) {
                reply.entry(
                    &ttl_for_is_dir(inode.attr.is_dir),
                    &inode.attr.to_fuse_attr(current_uid(), current_gid()),
                    0,
                );
                return;
            }
        }

        if is_platform_special(name_str) {
            reply.error(libc::ENOENT);
            return;
        }

        // Check if parent is a folder with unloaded children (lazy loading)
        // OR if the parent folder metadata is stale and needs a background refresh.
        // This mirrors readdir's staleness check so that file access (stat, open)
        // also triggers metadata refresh, not only directory listings.
        let (needs_load, needs_refresh) = {
            if let Some(parent_inode) = fs.inodes.get(parent) {
                match &parent_inode.kind {
                    InodeKind::Folder {
                        children_loaded,
                        ipns_name,
                        folder_key,
                        ..
                    } => {
                        if !children_loaded {
                            (Some((ipns_name.clone(), folder_key.clone())), None)
                        } else if fs.metadata_cache.get(ipns_name).is_none() {
                            (None, Some((ipns_name.clone(), folder_key.clone())))
                        } else {
                            (None, None)
                        }
                    }
                    InodeKind::Root { ipns_name, .. } => {
                        let stale = ipns_name.as_ref().and_then(|name| {
                            if fs.metadata_cache.get(name).is_none() {
                                Some((name.clone(), fs.root_folder_key.clone()))
                            } else {
                                None
                            }
                        });
                        (None, stale)
                    }
                    _ => (None, None),
                }
            } else {
                reply.error(libc::ENOENT);
                return;
            }
        };

        // Non-blocking stale metadata refresh (same as readdir's staleness check)
        if let Some((ipns_name, folder_key)) =
            needs_refresh.filter(|(n, _)| !fs.refreshing_metadata.contains(n))
        {
            fs.refreshing_metadata.insert(ipns_name.clone());
            crate::spawn_metadata_refresh(
                &fs.rt,
                fs.api.clone(),
                fs.refresh_tx.clone(),
                parent,
                ipns_name,
                folder_key,
            );
        }

        // Non-blocking lazy load: fire background fetch
        if let Some((ipns_name, folder_key)) =
            needs_load.filter(|(n, _)| !fs.refreshing_metadata.contains(n))
        {
            fs.refreshing_metadata.insert(ipns_name.clone());
            crate::spawn_metadata_refresh(
                &fs.rt,
                fs.api.clone(),
                fs.refresh_tx.clone(),
                parent,
                ipns_name,
                folder_key,
            );
            reply.error(libc::ENOENT);
            return;
        }

        if let Some(child_ino) = fs.inodes.find_child(parent, name_str) {
            if let Some(inode) = fs.inodes.get(child_ino) {
                reply.entry(
                    &ttl_for_is_dir(inode.attr.is_dir),
                    &inode.attr.to_fuse_attr(current_uid(), current_gid()),
                    0,
                );
                return;
            }
        }

        reply.error(libc::ENOENT);
    }

    /// Return file attributes for an inode.
    pub fn handle_getattr(fs: &mut CipherBoxFS, ino: u64, reply: ReplyAttr) {
        fs.drain_upload_completions();
        fs.drain_filepointer_completions();

        if let Some(inode) = fs.inodes.get(ino) {
            reply.attr(
                &ttl_for_is_dir(inode.attr.is_dir),
                &inode.attr.to_fuse_attr(current_uid(), current_gid()),
            );
        } else {
            reply.error(libc::ENOENT);
        }
    }

    /// Open a file for reading or writing.
    pub fn handle_open(fs: &mut CipherBoxFS, ino: u64, flags: i32, reply: ReplyOpen) {
        let file_info = match fs.inodes.get(ino) {
            Some(inode) => match &inode.kind {
                InodeKind::File {
                    cid,
                    encrypted_file_key,
                    iv,
                    encryption_mode,
                    ..
                } => Some((
                    cid.clone(),
                    encrypted_file_key.clone(),
                    iv.clone(),
                    encryption_mode.clone(),
                )),
                _ => {
                    reply.error(libc::EISDIR);
                    return;
                }
            },
            None => {
                reply.error(libc::ENOENT);
                return;
            }
        };

        let (cid, encrypted_file_key, iv, encryption_mode) = {
            let mut info = file_info.unwrap();
            if info.0.is_empty() {
                let is_unresolved = fs
                    .inodes
                    .get(ino)
                    .map(|i| {
                        matches!(
                            &i.kind,
                            InodeKind::File {
                                file_meta_resolved: false,
                                ..
                            }
                        )
                    })
                    .unwrap_or(false);

                if is_unresolved {
                    log::debug!("open: ino={} is unresolved FilePointer, polling...", ino);
                    match poll_filepointer_resolution(fs, ino) {
                        PollResult::Resolved => {
                            if let Some(inode) = fs.inodes.get(ino) {
                                if let InodeKind::File {
                                    cid,
                                    encrypted_file_key,
                                    iv,
                                    encryption_mode,
                                    ..
                                } = &inode.kind
                                {
                                    info = (
                                        cid.clone(),
                                        encrypted_file_key.clone(),
                                        iv.clone(),
                                        encryption_mode.clone(),
                                    );
                                }
                            }
                        }
                        PollResult::TimedOut => {
                            log::warn!(
                                "open: ino={} timed out after {}s poll-wait, returning EIO",
                                ino,
                                FILEPOINTER_POLL_TIMEOUT.as_secs()
                            );
                        }
                        PollResult::NotInFlight => {
                            log::warn!("open: ino={} no in-flight resolution (previously failed?), returning EIO", ino);
                        }
                    }
                    if info.0.is_empty() {
                        reply.error(libc::EIO);
                        return;
                    }
                }
            }
            info
        };
        let access_mode = flags & libc::O_ACCMODE;

        log::debug!(
            "open: ino={} flags=0x{:x} access_mode=0x{:x} O_TRUNC={} cid={}",
            ino,
            flags,
            access_mode,
            (flags & libc::O_TRUNC) != 0,
            &cid
        );

        if access_mode == libc::O_WRONLY || access_mode == libc::O_RDWR {
            let is_trunc = (flags & libc::O_TRUNC) != 0;

            let inode_size = fs.inodes.get(ino).map(|i| i.attr.size).unwrap_or(0);

            let existing_content = if is_trunc || inode_size == 0 {
                if let Some(inode) = fs.inodes.get_mut(ino) {
                    inode.attr.size = 0;
                    inode.attr.blocks = 0;
                    inode.attr.mtime = SystemTime::now();
                    inode.write_generation += 1;
                    if let InodeKind::File {
                        size: ref mut s,
                        cid: ref mut c,
                        ..
                    } = inode.kind
                    {
                        *s = 0;
                        *c = String::new();
                    }
                }
                None
            } else if !cid.is_empty() {
                fs.drain_content_prefetches();
                if let Some(cached) = fs.content_cache.get(&cid) {
                    Some(cached.to_vec())
                } else {
                    match fetch_and_decrypt_file_content(
                        fs,
                        &cid,
                        &encrypted_file_key,
                        &iv,
                        &encryption_mode,
                    ) {
                        Ok(content) => Some(content),
                        Err(e) => {
                            log::error!("Failed to fetch content for write-open: {}", e);
                            reply.error(libc::EIO);
                            return;
                        }
                    }
                }
            } else {
                None
            };

            let fh = fs.next_fh.fetch_add(1, Ordering::SeqCst);
            match OpenFileHandle::new_write(ino, &fs.temp_dir, existing_content.as_deref()) {
                Ok(handle) => {
                    fs.open_files.insert(fh, handle);
                    reply.opened(fh, FOPEN_DIRECT_IO);
                }
                Err(e) => {
                    log::error!("Failed to create write handle: {}", e);
                    reply.error(libc::EIO);
                }
            }
        } else {
            // Read-only open
            fs.drain_content_prefetches();

            if !cid.is_empty()
                && fs.content_cache.get(&cid).is_none()
                && !fs.prefetching.contains(&cid)
            {
                let api = fs.api.clone();
                let rt = fs.rt.clone();
                let tx = fs.content_tx.clone();
                let cid_clone = cid.clone();
                let efk = encrypted_file_key.clone();
                let iv_clone = iv.clone();
                let enc_mode = encryption_mode.clone();
                let pk = fs.private_key.clone();
                fs.prefetching.insert(cid.clone());

                rt.spawn(async move {
                    let result = tokio::time::timeout(
                        CONTENT_DOWNLOAD_TIMEOUT,
                        fetch_and_decrypt_content_async(
                            &api, &cid_clone, &efk, &iv_clone, &enc_mode, &pk,
                        ),
                    )
                    .await;

                    match result {
                        Ok(Ok(plaintext)) => {
                            log::debug!(
                                "prefetch: cached {} bytes for CID {}",
                                plaintext.len(),
                                &cid_clone[..cid_clone.len().min(12)]
                            );
                            let _ = tx.send(crate::PendingContent::Success {
                                cid: cid_clone,
                                data: plaintext,
                            });
                        }
                        Ok(Err(e)) => {
                            log::error!("Prefetch failed for CID {}: {}", cid_clone, e);
                            let _ = tx.send(crate::PendingContent::Failure { cid: cid_clone });
                        }
                        Err(_) => {
                            log::error!(
                                "Prefetch timed out for CID {} ({}s)",
                                cid_clone,
                                CONTENT_DOWNLOAD_TIMEOUT.as_secs()
                            );
                            let _ = tx.send(crate::PendingContent::Failure { cid: cid_clone });
                        }
                    }
                });
            }

            let fh = fs.next_fh.fetch_add(1, Ordering::SeqCst);
            fs.open_files.insert(fh, OpenFileHandle::new_read(ino));
            reply.opened(fh, FOPEN_DIRECT_IO);
        }
    }

    /// Read file content.
    pub fn handle_read(
        fs: &mut CipherBoxFS,
        ino: u64,
        fh: u64,
        offset: i64,
        size: u32,
        reply: ReplyData,
    ) {
        fs.drain_content_prefetches();

        let has_temp = fs
            .open_files
            .get(&fh)
            .map(|h| h.temp_path.is_some())
            .unwrap_or(false);

        log::debug!(
            "read: ino={} fh={} offset={} size={} has_temp={}",
            ino,
            fh,
            offset,
            size,
            has_temp
        );

        if has_temp {
            if let Some(handle) = fs.open_files.get(&fh) {
                match handle.read_at(offset, size) {
                    Ok(data) => {
                        log::debug!("read: temp file returned {} bytes", data.len());
                        reply.data(&data);
                        return;
                    }
                    Err(e) => {
                        log::error!("Temp file read failed: {}", e);
                        reply.error(libc::EIO);
                        return;
                    }
                }
            } else {
                reply.error(libc::EBADF);
                return;
            }
        }

        let (cid, encrypted_file_key_hex, iv_hex, encryption_mode) = {
            match fs.inodes.get(ino) {
                Some(inode) => match &inode.kind {
                    InodeKind::File {
                        cid,
                        encrypted_file_key,
                        iv,
                        encryption_mode,
                        ..
                    } => (
                        cid.clone(),
                        encrypted_file_key.clone(),
                        iv.clone(),
                        encryption_mode.clone(),
                    ),
                    _ => {
                        reply.error(libc::EISDIR);
                        return;
                    }
                },
                None => {
                    reply.error(libc::ENOENT);
                    return;
                }
            }
        };

        if cid.is_empty() {
            let is_unresolved = fs
                .inodes
                .get(ino)
                .map(|i| {
                    matches!(
                        &i.kind,
                        InodeKind::File {
                            file_meta_resolved: false,
                            ..
                        }
                    )
                })
                .unwrap_or(false);

            if is_unresolved {
                log::debug!("read: ino={} is unresolved FilePointer, polling...", ino);
                let poll_result = poll_filepointer_resolution(fs, ino);
                if matches!(poll_result, PollResult::Resolved) {
                    if let Some(inode) = fs.inodes.get(ino) {
                        if let InodeKind::File {
                            cid,
                            encrypted_file_key,
                            iv,
                            encryption_mode,
                            file_meta_resolved: true,
                            ..
                        } = &inode.kind
                        {
                            if !cid.is_empty() {
                                // Re-extract file info for the normal read path
                                let new_cid = cid.clone();
                                let new_efk = encrypted_file_key.clone();
                                let new_iv = iv.clone();
                                let new_em = encryption_mode.clone();
                                // Check cache first
                                if let Some(cached) = fs.content_cache.get(&new_cid) {
                                    let start = offset as usize;
                                    if start >= cached.len() {
                                        reply.data(&[]);
                                        return;
                                    }
                                    let end = std::cmp::min(start + size as usize, cached.len());
                                    let data_slice = cached[start..end].to_vec();
                                    if let Some(handle) = fs.open_files.get_mut(&fh) {
                                        handle.cached_content = Some(cached.to_vec());
                                    }
                                    reply.data(&data_slice);
                                    return;
                                }
                                // Not cached yet -- trigger prefetch, NFS/SMB will retry
                                if !fs.prefetching.contains(&new_cid) {
                                    let api = fs.api.clone();
                                    let rt = fs.rt.clone();
                                    let tx = fs.content_tx.clone();
                                    let cid_clone = new_cid.clone();
                                    let efk = new_efk;
                                    let iv_clone = new_iv;
                                    let enc_mode = new_em;
                                    let pk = fs.private_key.clone();
                                    fs.prefetching.insert(new_cid);

                                    rt.spawn(async move {
                                        let result = tokio::time::timeout(
                                            CONTENT_DOWNLOAD_TIMEOUT,
                                            fetch_and_decrypt_content_async(
                                                &api, &cid_clone, &efk, &iv_clone, &enc_mode, &pk,
                                            ),
                                        ).await;
                                        match result {
                                            Ok(Ok(plaintext)) => {
                                                let _ = tx.send(crate::PendingContent::Success { cid: cid_clone, data: plaintext });
                                            }
                                            Ok(Err(e)) => {
                                                log::error!("Read prefetch (post-FP-resolve) failed for CID {}: {}", cid_clone, e);
                                                let _ = tx.send(crate::PendingContent::Failure { cid: cid_clone });
                                            }
                                            Err(_) => {
                                                log::error!("Read prefetch (post-FP-resolve) timed out for CID {}", cid_clone);
                                                let _ = tx.send(crate::PendingContent::Failure { cid: cid_clone });
                                            }
                                        }
                                    });
                                }
                                reply.error(libc::EIO); // NFS/SMB will retry, prefetch will populate cache
                                return;
                            }
                        }
                    }
                }
                match poll_result {
                    PollResult::TimedOut => log::warn!(
                        "read: ino={} timed out after {}s poll-wait, returning EIO",
                        ino,
                        FILEPOINTER_POLL_TIMEOUT.as_secs()
                    ),
                    PollResult::NotInFlight => log::warn!(
                        "read: ino={} no in-flight resolution (previously failed?), returning EIO",
                        ino
                    ),
                    PollResult::Resolved => {} // handled above
                }
                reply.error(libc::EIO);
                return;
            }

            // Not an unresolved FilePointer -- fall through to existing empty-CID handling
            if let Some(content) = fs.pending_content.get(&ino) {
                let start = offset as usize;
                if start >= content.len() {
                    reply.data(&[]);
                } else {
                    let end = std::cmp::min(start + size as usize, content.len());
                    reply.data(&content[start..end]);
                }
                return;
            }
            reply.data(&[]);
            return;
        }

        if let Some(handle) = fs.open_files.get(&fh) {
            if let Some(ref content) = handle.cached_content {
                let start = offset as usize;
                if start >= content.len() {
                    reply.data(&[]);
                    return;
                }
                let end = std::cmp::min(start + size as usize, content.len());
                reply.data(&content[start..end]);
                return;
            }
        }

        if let Some(cached) = fs.content_cache.get(&cid) {
            let start = offset as usize;
            if start >= cached.len() {
                reply.data(&[]);
                return;
            }
            let end = std::cmp::min(start + size as usize, cached.len());
            let data_slice = cached[start..end].to_vec();
            if let Some(handle) = fs.open_files.get_mut(&fh) {
                handle.cached_content = Some(cached.to_vec());
            }
            reply.data(&data_slice);
            return;
        }

        // Content not in cache -- start prefetch and poll
        if !fs.prefetching.contains(&cid) {
            let api = fs.api.clone();
            let rt = fs.rt.clone();
            let tx = fs.content_tx.clone();
            let cid_clone = cid.clone();
            let efk = encrypted_file_key_hex.clone();
            let iv_clone = iv_hex.clone();
            let enc_mode = encryption_mode.clone();
            let pk = fs.private_key.clone();
            fs.prefetching.insert(cid.clone());

            rt.spawn(async move {
                let result = tokio::time::timeout(
                    CONTENT_DOWNLOAD_TIMEOUT,
                    fetch_and_decrypt_content_async(
                        &api, &cid_clone, &efk, &iv_clone, &enc_mode, &pk,
                    ),
                )
                .await;

                match result {
                    Ok(Ok(plaintext)) => {
                        log::debug!(
                            "prefetch(read): cached {} bytes for CID {}",
                            plaintext.len(),
                            &cid_clone[..cid_clone.len().min(12)]
                        );
                        let _ = tx.send(crate::PendingContent::Success {
                            cid: cid_clone,
                            data: plaintext,
                        });
                    }
                    Ok(Err(e)) => {
                        log::error!("Read prefetch failed for CID {}: {}", cid_clone, e);
                        let _ = tx.send(crate::PendingContent::Failure { cid: cid_clone });
                    }
                    Err(_) => {
                        log::error!("Read prefetch timed out for CID {}", cid_clone);
                        let _ = tx.send(crate::PendingContent::Failure { cid: cid_clone });
                    }
                }
            });
        }

        let poll_start = std::time::Instant::now();
        let max_wait = Duration::from_secs(3);
        loop {
            std::thread::sleep(Duration::from_millis(100));
            fs.drain_content_prefetches();
            if let Some(cached) = fs.content_cache.get(&cid) {
                log::debug!(
                    "FUSE read: content ready after {:.1}s for CID {}",
                    poll_start.elapsed().as_secs_f64(),
                    &cid[..cid.len().min(12)]
                );
                let start = offset as usize;
                if start >= cached.len() {
                    reply.data(&[]);
                } else {
                    let end = std::cmp::min(start + size as usize, cached.len());
                    reply.data(&cached[start..end]);
                }
                return;
            }
            if poll_start.elapsed() > max_wait {
                break;
            }
        }

        reply.error(libc::EIO);
    }

    /// Release (close) a file handle.
    pub fn handle_release(fs: &mut CipherBoxFS, ino: u64, fh: u64, reply: ReplyEmpty) {
        fs.drain_upload_completions();

        let handle = fs.open_files.remove(&fh);

        if let Some(handle) = handle {
            let is_new_file = handle.temp_path.is_some() && {
                fs.inodes
                    .get(ino)
                    .map(|i| match &i.kind {
                        InodeKind::File { cid, .. } => cid.is_empty(),
                        _ => false,
                    })
                    .unwrap_or(false)
            };
            let needs_upload = handle.temp_path.is_some() && (handle.dirty || is_new_file);
            if needs_upload {
                log::debug!(
                    "release: uploading ino {} (dirty={}, new={})",
                    ino,
                    handle.dirty,
                    is_new_file
                );

                // Build the journal entry via the shared helper (journal_helpers.rs),
                // then fsync + apply in-memory mutations.
                //
                // CR-04: all in-memory mutations (inode kind/attr, pending_content,
                // queued publish) are deferred until AFTER the journal entry is fsynced.
                // If the helper or journal.put fails, the Err arm replies EIO having
                // mutated nothing, so the debounced publisher never emits metadata for a
                // write the OS was told failed.
                let build_result =
                    (|| -> Result<crate::journal_helpers::UploadJournalResult, String> {
                        // Steps 1-7: encrypt, wrap, resolve parent IPNS, build JournalEntry.
                        let result = fs.build_upload_journal_entry(ino, &handle, is_new_file)?;

                        // CR-07: clone the entry before put() so the snapshot can be carried
                        // into the spawn closure for record_failure on upload failure.
                        let entry_snapshot = result.entry.clone();

                        // D-04: fsync journal entry to disk BEFORE acking the OS.
                        fs.journal.put(&result.entry)?;

                        // CR-04: journal is durably committed — now apply the in-memory write.
                        if let Some(inode) = fs.inodes.get_mut(ino) {
                            let cached_hex = match &inode.kind {
                                InodeKind::File {
                                    file_ipns_key_encrypted_hex,
                                    ..
                                } => file_ipns_key_encrypted_hex.clone(),
                                _ => None,
                            };
                            inode.kind = InodeKind::File {
                                cid: String::new(),
                                encrypted_file_key: result.encrypted_file_key_hex.clone(),
                                iv: result.iv_hex.clone(),
                                size: result.file_size,
                                encryption_mode: "GCM".to_string(),
                                file_meta_ipns_name: result.file_meta_ipns_name.clone(),
                                file_meta_resolved: true,
                                file_ipns_private_key: result.file_ipns_private_key.clone(),
                                file_ipns_key_encrypted_hex: cached_hex,
                                versions: result.versions_for_meta.clone(),
                            };
                            inode.attr.size = result.file_size;
                            inode.attr.blocks = (result.file_size + 511) / 512;
                            inode.attr.mtime = SystemTime::now();
                        }

                        fs.pending_content.insert(ino, result.plaintext.clone());

                        fs.queue_publish(result.parent_ino, true);

                        // Return the full result + snapshot for the spawn block.
                        // We smuggle the snapshot by storing it in a wrapper; the
                        // spawn block will destructure it from there.
                        let _ = entry_snapshot; // consumed above via .clone(); held in result.entry
                        Ok(result)
                    })();

                match build_result {
                    Ok(result) => {
                        // CR-07: snapshot the entry (already put to disk) for record_failure.
                        let journal_entry_snapshot = result.entry.clone();

                        let crate::journal_helpers::UploadJournalResult {
                            ciphertext,
                            file_meta,
                            file_ipns_private_key,
                            file_meta_ipns_name,
                            folder_key_for_file_meta,
                            parent_ino,
                            old_file_cid,
                            pruned_cids,
                            write_gen,
                            ..
                        } = result;
                        let spawn_ino = ino;

                        let api = fs.api.clone();
                        let rt = fs.rt.clone();
                        let upload_tx = fs.upload_tx.clone();
                        let coordinator = fs.publish_coordinator.clone();
                        let tee_public_key = fs.tee_public_key.clone();
                        let tee_key_epoch = fs.tee_key_epoch;
                        let spawn_journal = fs.journal.clone();

                        // D-05: zeroize and delete plaintext temp file BEFORE acking OS.
                        handle.cleanup();
                        // D-04: ack OS only after local journal fsync is confirmed above.
                        reply.ok();

                        // Spawn background upload AFTER ack; entry stays in journal until
                        // success, preserving the write_generation stale-drain guard.
                        std::thread::spawn(move || {
                            let result = rt.block_on(async {
                                let file_cid = cipherbox_api_client::ipfs::upload_content(
                                    &api, &ciphertext,
                                ).await.map_err(|e| format!("{}", e))?;

                                log::info!("File uploaded: ino {} -> CID {}", spawn_ino, file_cid);

                                let _ = upload_tx.send(crate::FsEvent::UploadComplete(crate::UploadComplete {
                                    ino: spawn_ino,
                                    new_cid: file_cid.clone(),
                                    parent_ino,
                                    old_file_cid,
                                    pruned_cids,
                                    write_generation: write_gen,
                                }));

                                if let (Some(ipns_key), Some(ipns_name), Some(folder_key)) =
                                    (&file_ipns_private_key, &file_meta_ipns_name, &folder_key_for_file_meta)
                                {
                                    let mut file_meta_with_cid = file_meta;
                                    file_meta_with_cid.cid = file_cid;

                                    if let Err(e) = publish_file_metadata(
                                        &api, &file_meta_with_cid, folder_key, ipns_key, ipns_name, &coordinator,
                                        tee_public_key.as_deref(),
                                        tee_key_epoch,
                                        is_new_file,
                                    ).await {
                                        log::warn!("Per-file IPNS publish failed for ino {}: {}", spawn_ino, e);
                                    }
                                } else {
                                    log::warn!(
                                        "release: skipping per-file IPNS publish for ino {} (missing key/name/folder_key)",
                                        spawn_ino
                                    );
                                }

                                // CR-08 (mechanism b): do NOT remove the journal entry here.
                                // The parent folder pointer is published by the debounced
                                // publisher AFTER this thread exits. Removing the entry before
                                // that publish is confirmed creates an irrecoverable orphan
                                // window on crash. Replay is the authoritative cleanup path:
                                // replay's already_present check returns Ok and the caller
                                // removes the entry once the child is confirmed in the parent
                                // metadata on the next mount.

                                Ok::<(), String>(())
                            });

                            if let Err(e) = result {
                                // CR-07: call record_failure so retries increment and the entry
                                // parks as Failed after max_retries (D-09). Never silently drop.
                                if let Err(re) =
                                    spawn_journal.record_failure(&journal_entry_snapshot, &e)
                                {
                                    log::warn!(
                                        "record_failure failed for ino {}: {}",
                                        spawn_ino,
                                        re
                                    );
                                }
                                log::error!(
                                    "Background upload failed for ino {}: {}",
                                    spawn_ino,
                                    e
                                );
                            }
                        });
                        return; // reply already sent
                    }
                    Err(e) => {
                        // CR-04: reply EIO and return — do NOT fall through to reply.ok().
                        // All in-memory mutations (inode kind/attr, pending_content, queued
                        // publish) are deferred until after the journal fsync, so a failure
                        // here has mutated nothing: no rollback needed, and no journal entry
                        // was fsynced, so there is nothing to remove.
                        log::error!("File upload preparation failed for ino {}: {}", ino, e);
                        handle.cleanup();
                        reply.error(libc::EIO);
                        return;
                    }
                }
            }
        }

        reply.ok();
    }

    /// Flush file data (no-op).
    pub fn handle_flush(reply: ReplyEmpty) {
        reply.ok();
    }

    /// Check file access permissions.
    pub fn handle_access(fs: &CipherBoxFS, ino: u64, mask: i32, reply: ReplyEmpty) {
        if fs.inodes.get(ino).is_none() {
            reply.error(libc::ENOENT);
            return;
        }
        log::trace!("access: ino={} mask={:#o} -> OK", ino, mask);
        reply.ok();
    }

    /// Get extended attribute value.
    pub fn handle_getxattr(reply: ReplyXattr) {
        #[cfg(target_os = "macos")]
        {
            reply.error(libc::ENOATTR);
        }
        #[cfg(not(target_os = "macos"))]
        {
            reply.error(libc::ENODATA);
        }
    }

    /// List extended attribute names.
    pub fn handle_listxattr(size: u32, reply: ReplyXattr) {
        if size == 0 {
            reply.size(0);
        } else {
            reply.data(&[]);
        }
    }
}

//! Write operations for macOS FUSE filesystem.
//!
//! Contains handler logic for: write, create, setattr, rename, unlink, rmdir, mkdir.

#[cfg(feature = "fuse")]
pub(crate) mod implementation {
    use fuser::{ReplyAttr, ReplyCreate, ReplyEmpty, ReplyEntry, ReplyWrite};
    use std::ffi::OsStr;
    use std::sync::atomic::Ordering;
    use std::time::SystemTime;

    use crate::file_handle::OpenFileHandle;
    use crate::helpers::is_platform_special;
    use crate::inode::{FileAttrs, InodeData, InodeKind};
    use crate::operations::implementation::{
        current_gid, current_uid, ttl_for_is_dir, DIR_TTL, FILE_TTL,
    };
    use crate::CipherBoxFS;

    /// Set file attributes (handles truncate via size parameter).
    pub fn handle_setattr(
        fs: &mut CipherBoxFS,
        ino: u64,
        size: Option<u64>,
        fh: Option<u64>,
        reply: ReplyAttr,
    ) {
        log::debug!("setattr: ino={} size={:?} fh={:?}", ino, size, fh);
        if let Some(new_size) = size {
            if let Some(fh_id) = fh {
                if let Some(handle) = fs.open_files.get_mut(&fh_id) {
                    if handle.temp_path.is_some() {
                        if let Err(e) = handle.truncate(new_size) {
                            log::error!("Truncate failed for ino {}: {}", ino, e);
                            reply.error(libc::EIO);
                            return;
                        }
                        handle.dirty = true;
                    }
                }
            } else {
                // No explicit fh -- find open writable handle for this inode
                let matching_fh: Option<u64> = fs
                    .open_files
                    .iter()
                    .find(|(_, h)| h.ino == ino && h.temp_path.is_some())
                    .map(|(id, _)| *id);
                if let Some(fh_id) = matching_fh {
                    if let Some(handle) = fs.open_files.get_mut(&fh_id) {
                        if let Err(e) = handle.truncate(new_size) {
                            log::error!("Truncate (no-fh) failed for ino {}: {}", ino, e);
                            reply.error(libc::EIO);
                            return;
                        }
                        handle.dirty = true;
                    }
                }
            }

            if let Some(inode) = fs.inodes.get_mut(ino) {
                inode.attr.size = new_size;
                inode.attr.blocks = (new_size + 511) / 512;
                inode.attr.mtime = SystemTime::now();

                if new_size == 0 {
                    inode.write_generation += 1;
                    if let InodeKind::File {
                        size: ref mut s,
                        cid: ref mut c,
                        ..
                    } = inode.kind
                    {
                        *s = 0;
                        *c = String::new();
                    }
                } else {
                    if let InodeKind::File {
                        size: ref mut s, ..
                    } = inode.kind
                    {
                        *s = new_size;
                    }
                }

                reply.attr(
                    &ttl_for_is_dir(inode.attr.is_dir),
                    &inode.attr.to_fuse_attr(current_uid(), current_gid()),
                );
                return;
            }
        }

        if let Some(inode) = fs.inodes.get(ino) {
            reply.attr(
                &ttl_for_is_dir(inode.attr.is_dir),
                &inode.attr.to_fuse_attr(current_uid(), current_gid()),
            );
        } else {
            reply.error(libc::ENOENT);
        }
    }

    /// Write data to an open file.
    pub fn handle_write(
        fs: &mut CipherBoxFS,
        ino: u64,
        fh: u64,
        offset: i64,
        data: &[u8],
        reply: ReplyWrite,
    ) {
        let handle = match fs.open_files.get_mut(&fh) {
            Some(h) => h,
            None => {
                reply.error(libc::EBADF);
                return;
            }
        };

        match handle.write_at(offset, data) {
            Ok(written) => {
                let new_end = offset as u64 + data.len() as u64;
                if let Some(inode) = fs.inodes.get_mut(ino) {
                    if new_end > inode.attr.size {
                        inode.attr.size = new_end;
                        inode.attr.blocks = (new_end + 511) / 512;
                    }
                    inode.attr.mtime = SystemTime::now();
                }
                reply.written(written as u32);
            }
            Err(e) => {
                log::error!("Write failed for ino {} fh {}: {}", ino, fh, e);
                reply.error(libc::EIO);
            }
        }
    }

    /// Create a new file in a directory.
    pub fn handle_create(
        fs: &mut CipherBoxFS,
        parent: u64,
        name: &OsStr,
        _flags: i32,
        reply: ReplyCreate,
    ) {
        let name_str = match name.to_str() {
            Some(n) => n,
            None => {
                reply.error(libc::EINVAL);
                return;
            }
        };

        if is_platform_special(name_str) {
            reply.error(libc::EACCES);
            return;
        }

        let parent_exists = fs.inodes.get(parent).map(|inode| {
            matches!(
                inode.kind,
                InodeKind::Root { .. } | InodeKind::Folder { .. }
            )
        });
        if parent_exists != Some(true) {
            reply.error(libc::ENOENT);
            return;
        }

        let ino = fs.inodes.allocate_ino();
        let now = SystemTime::now();

        let attr = FileAttrs {
            ino,
            size: 0,
            blocks: 0,
            atime: now,
            mtime: now,
            ctime: now,
            crtime: now,
            is_dir: false,
            perm: 0o666,
            nlink: 1,
        };
        let fuse_attr = attr.to_fuse_attr(current_uid(), current_gid());

        // Generate random Ed25519 IPNS keypair for this file
        let signing_key = ed25519_dalek::SigningKey::generate(&mut rand::rngs::OsRng);
        let verifying_key = signing_key.verifying_key();
        let file_ipns_private_key = signing_key.to_bytes().to_vec();
        let file_ipns_public_key_bytes: [u8; 32] = verifying_key.to_bytes();
        let file_ipns_name =
            match cipherbox_core::ipns::derive_ipns_name(&file_ipns_public_key_bytes) {
                Ok(name) => name,
                Err(e) => {
                    log::error!(
                        "create: IPNS name derivation from random keypair failed: {}",
                        e
                    );
                    reply.error(libc::EIO);
                    return;
                }
            };

        let ipns_key_encrypted_hex = match cipherbox_crypto::wrap_key(
            &file_ipns_private_key,
            &fs.public_key,
        ) {
            Ok(wrapped) => Some(hex::encode(&wrapped)),
            Err(e) => {
                log::error!("create: failed to ECIES-wrap IPNS key: {}. Cannot proceed without wrapped key.", e);
                reply.error(libc::EIO);
                return;
            }
        };

        let inode = InodeData {
            ino,
            parent_ino: parent,
            name: name_str.to_string(),
            kind: InodeKind::File {
                cid: String::new(),
                encrypted_file_key: String::new(),
                iv: String::new(),
                size: 0,
                encryption_mode: "GCM".to_string(),
                file_meta_ipns_name: Some(file_ipns_name),
                file_meta_resolved: true,
                file_ipns_private_key: Some(zeroize::Zeroizing::new(file_ipns_private_key)),
                file_ipns_key_encrypted_hex: ipns_key_encrypted_hex,
                versions: None,
            },
            attr,
            children: None,
            write_generation: 0,
        };

        fs.inodes.insert(inode);

        if let Some(parent_inode) = fs.inodes.get_mut(parent) {
            if let Some(ref mut children) = parent_inode.children {
                children.push(ino);
            }
            parent_inode.attr.mtime = SystemTime::now();
            parent_inode.attr.ctime = SystemTime::now();
        }

        let fh = fs.next_fh.fetch_add(1, Ordering::SeqCst);
        match OpenFileHandle::new_write(ino, &fs.temp_dir, None) {
            Ok(handle) => {
                fs.open_files.insert(fh, handle);
            }
            Err(e) => {
                log::error!("Failed to create temp file for new file: {}", e);
                fs.inodes.remove(ino);
                if let Some(parent_inode) = fs.inodes.get_mut(parent) {
                    if let Some(ref mut children) = parent_inode.children {
                        children.retain(|&child| child != ino);
                    }
                }
                reply.error(libc::EIO);
                return;
            }
        }

        fs.mutated_folders.insert(parent, std::time::Instant::now());

        log::debug!(
            "create: {} in parent {} -> ino {} fh {}",
            name_str,
            parent,
            ino,
            fh
        );
        reply.created(&FILE_TTL, &fuse_attr, 0, fh, 0);
    }

    /// Delete a file from a directory.
    pub fn handle_unlink(fs: &mut CipherBoxFS, parent: u64, name: &OsStr, reply: ReplyEmpty) {
        let name_str = match name.to_str() {
            Some(n) => n,
            None => {
                reply.error(libc::ENOENT);
                return;
            }
        };

        let child_ino = match fs.inodes.find_child(parent, name_str) {
            Some(ino) => ino,
            None => {
                reply.error(libc::ENOENT);
                return;
            }
        };

        // Capture data for bin entry before inode removal
        let bin_entry_data = match fs.inodes.get(child_ino) {
            Some(inode) => match &inode.kind {
                InodeKind::File {
                    file_meta_ipns_name,
                    file_ipns_key_encrypted_hex,
                    size,
                    cid,
                    versions,
                    ..
                } => {
                    let now_ms = SystemTime::now()
                        .duration_since(std::time::UNIX_EPOCH)
                        .unwrap_or_default()
                        .as_millis() as u64;
                    let created_ms = inode
                        .attr
                        .crtime
                        .duration_since(std::time::UNIX_EPOCH)
                        .unwrap_or_default()
                        .as_millis() as u64;

                    let meta_ipns = match file_meta_ipns_name {
                        Some(name) if !name.is_empty() => Some(name.clone()),
                        _ => {
                            // file_meta_ipns_name is optional for files loaded from
                            // remote metadata before IPNS resolve. Since bin publishing
                            // is best-effort, skip creating a bin entry when it's missing
                            // instead of failing the unlink.
                            log::warn!(
                                "unlink: missing file_meta_ipns_name for ino {}, skipping bin entry",
                                child_ino
                            );
                            None
                        }
                    };

                    if let Some(meta_ipns) = meta_ipns {
                        let file_pointer = cipherbox_core::folder::FilePointer {
                            id: cipherbox_crypto::utils::generate_uuid_v4(),
                            name: inode.name.clone(),
                            file_meta_ipns_name: meta_ipns,
                            ipns_private_key_encrypted: file_ipns_key_encrypted_hex.clone(),
                            created_at: if created_ms > 0 { created_ms } else { now_ms },
                            modified_at: now_ms,
                        };

                        let ver_cids = crate::helpers::versions_to_bin_entries(versions);
                        Some((
                            inode.name.clone(),
                            *size,
                            file_pointer,
                            cid.clone(),
                            ver_cids,
                        ))
                    } else {
                        None
                    }
                }
                _ => {
                    reply.error(libc::EISDIR);
                    return;
                }
            },
            None => {
                reply.error(libc::ENOENT);
                return;
            }
        };

        log::debug!("unlink: {} from parent {}", name_str, parent);

        let now = SystemTime::now();

        fs.inodes.remove(child_ino);

        if let Some(parent_inode) = fs.inodes.get_mut(parent) {
            parent_inode.attr.mtime = now;
            parent_inode.attr.ctime = now;
        }

        if let Err(e) = fs.update_folder_metadata(parent) {
            log::error!("Failed to update folder metadata after unlink: {}", e);
        }

        // Create bin entry and publish to bin IPNS (fire-and-forget)
        if let Some((item_name, file_size, file_pointer, content_cid, ver_cids)) = bin_entry_data {
            let parent_ipns_name = fs
                .inodes
                .get(parent)
                .map(|p| match &p.kind {
                    InodeKind::Root { ipns_name, .. } => ipns_name.clone().unwrap_or_default(),
                    InodeKind::Folder { ipns_name, .. } => ipns_name.clone(),
                    _ => String::new(),
                })
                .unwrap_or_default();

            if parent_ipns_name.is_empty() {
                log::warn!(
                    "unlink: missing parent IPNS name for parent ino {}, skipping bin publish",
                    parent
                );
            } else {
                let parent_path = crate::helpers::build_folder_path(fs, parent);

                let bin_entry = cipherbox_core::bin::BinEntry {
                    id: cipherbox_crypto::utils::generate_uuid_v4(),
                    item_type: cipherbox_core::bin::BinItemType::File,
                    name: item_name.clone(),
                    original_parent_ipns_name: parent_ipns_name,
                    original_path: parent_path,
                    deleted_at: now
                        .duration_since(std::time::UNIX_EPOCH)
                        .unwrap_or_default()
                        .as_millis() as u64,
                    size: file_size,
                    mime_type: cipherbox_crypto::utils::mime_from_extension(&item_name).to_string(),
                    content_cid: if content_cid.is_empty() {
                        None
                    } else {
                        Some(content_cid)
                    },
                    content_size: Some(file_size),
                    version_cids: ver_cids,
                    file_pointer: Some(file_pointer),
                    folder_entry: None,
                };

                crate::spawn_bin_entry_publish(
                    fs.api.clone(),
                    fs.rt.clone(),
                    bin_entry,
                    fs.private_key.clone(),
                    fs.public_key.to_vec(),
                    fs.publish_coordinator.clone(),
                );
            }
        }

        reply.ok();
    }

    /// Create a new directory.
    pub fn handle_mkdir(fs: &mut CipherBoxFS, parent: u64, name: &OsStr, reply: ReplyEntry) {
        let name_str = match name.to_str() {
            Some(n) => n,
            None => {
                reply.error(libc::EINVAL);
                return;
            }
        };

        if is_platform_special(name_str) {
            reply.error(libc::EACCES);
            return;
        }

        let parent_exists = fs.inodes.get(parent).map(|inode| {
            matches!(
                inode.kind,
                InodeKind::Root { .. } | InodeKind::Folder { .. }
            )
        });
        if parent_exists != Some(true) {
            reply.error(libc::ENOENT);
            return;
        }

        log::debug!("mkdir: {} in parent {}", name_str, parent);

        let result = (|| -> Result<fuser::FileAttr, String> {
            let folder_key = cipherbox_crypto::utils::generate_file_key();

            let (ipns_public_key, ipns_private_key) = cipherbox_crypto::generate_ed25519_keypair();

            let ipns_pub_arr: [u8; 32] = ipns_public_key
                .clone()
                .try_into()
                .map_err(|_| "Invalid IPNS public key length".to_string())?;
            let ipns_name = cipherbox_core::ipns::derive_ipns_name(&ipns_pub_arr)
                .map_err(|e| format!("Failed to derive IPNS name: {}", e))?;

            let wrapped_folder_key = cipherbox_crypto::wrap_key(&folder_key, &fs.public_key)
                .map_err(|e| format!("Folder key wrapping failed: {}", e))?;
            let encrypted_folder_key_hex = hex::encode(&wrapped_folder_key);
            // Clone for use in the journal entry (original is moved into the inode below).
            let encrypted_folder_key_hex_for_journal = encrypted_folder_key_hex.clone();

            let ino = fs.inodes.allocate_ino();
            let now = SystemTime::now();

            let attr = FileAttrs {
                ino,
                size: 0,
                blocks: 0,
                atime: now,
                mtime: now,
                ctime: now,
                crtime: now,
                is_dir: true,
                perm: 0o777,
                nlink: 2,
            };
            let fuse_attr = attr.to_fuse_attr(current_uid(), current_gid());

            let inode = InodeData {
                ino,
                parent_ino: parent,
                name: name_str.to_string(),
                kind: InodeKind::Folder {
                    ipns_name: ipns_name.clone(),
                    encrypted_folder_key: encrypted_folder_key_hex,
                    folder_key: zeroize::Zeroizing::new(folder_key.to_vec()),
                    ipns_private_key: Some(ipns_private_key.clone()),
                    children_loaded: true,
                },
                attr,
                children: Some(vec![]),
                write_generation: 0,
            };

            fs.inodes.insert(inode);

            if let Some(parent_inode) = fs.inodes.get_mut(parent) {
                if let Some(ref mut children) = parent_inode.children {
                    children.push(ino);
                }
                parent_inode.attr.mtime = SystemTime::now();
                parent_inode.attr.ctime = SystemTime::now();
            }

            // Build the JournalEntry via the shared helper (journal_helpers.rs).
            // The helper handles: initial metadata encryption, TEE-wrap, build_folder_metadata,
            // ECIES-wrap of parent + child IPNS keys, and JournalOp::MkdirPublish construction.
            // D-04: the helper does NOT call journal.put — we do that here for the fsync barrier.
            // Roll back the in-memory inode insert + parent children/mtime update if the
            // journal entry can't be built or fsynced. Otherwise a failed mkdir returns an
            // error to the OS but leaves a ghost directory in the inode table with no durable
            // replay record. InodeTable::remove cleans the inode, name index, and parent's
            // children entry.
            let mkdir_result = match fs.build_mkdir_journal_entry(
                parent,
                ino,
                name_str,
                &folder_key,
                &ipns_name,
                ipns_private_key.clone(),
                &encrypted_folder_key_hex_for_journal,
            ) {
                Ok(result) => result,
                Err(e) => {
                    fs.inodes.remove(ino);
                    return Err(e);
                }
            };

            let mkdir_journal_entry_id = mkdir_result.entry.id.clone();

            // D-04: fsync journal entry to disk BEFORE reply.entry().
            // This closes the crash-before-thread-runs window (T-43-07 / D-11b).
            if let Err(e) = fs.journal.put(&mkdir_result.entry) {
                fs.inodes.remove(ino);
                return Err(e);
            }

            let crate::journal_helpers::MkdirJournalResult {
                json_bytes,
                ipns_private_key: ipns_private_key_zeroized,
                encrypted_ipns_for_tee,
                tee_key_epoch,
                ipns_name: ipns_name_clone,
                parent_metadata,
                parent_folder_key,
                parent_ipns_key,
                parent_ipns_name,
                parent_old_cid,
                ..
            } = mkdir_result;

            let api = fs.api.clone();
            let rt = fs.rt.clone();
            let coordinator = fs.publish_coordinator.clone();
            let upload_tx = fs.upload_tx.clone();
            let journal_for_mkdir = fs.journal.clone();
            let parent_ino = parent;

            std::thread::spawn(move || {
                let result = rt.block_on(async {
                    let initial_cid = cipherbox_api_client::ipfs::upload_content(
                        &api, &json_bytes,
                    ).await.map_err(|e| format!("{}", e))?;

                    let ipns_key_arr: [u8; 32] = (*ipns_private_key_zeroized).clone().try_into()
                        .map_err(|_| "Invalid IPNS key length".to_string())?;
                    let value = format!("/ipfs/{}", initial_cid);
                    let record = cipherbox_core::ipns::create_ipns_record(
                        &ipns_key_arr, &value, 0, 86_400_000,
                    ).map_err(|e| format!("IPNS record creation failed: {}", e))?;
                    let marshaled = cipherbox_core::ipns::marshal_ipns_record(&record)
                        .map_err(|e| format!("IPNS marshal failed: {}", e))?;

                    use base64::Engine;
                    let record_b64 = base64::engine::general_purpose::STANDARD
                        .encode(&marshaled);

                    // New folder initial publish: sequence 0, no conflict check needed
                    let req = cipherbox_api_client::IpnsPublishRequest {
                        ipns_name: ipns_name_clone.clone(),
                        record: record_b64,
                        metadata_cid: initial_cid,
                        encrypted_ipns_private_key: encrypted_ipns_for_tee,
                        key_epoch: tee_key_epoch,
                        expected_sequence_number: None,
                    };
                    match cipherbox_api_client::ipns::publish_ipns(&api, &req).await.map_err(|e| format!("{}", e))? {
                        cipherbox_api_client::PublishResult::Success => {
                            coordinator.record_publish(&ipns_name_clone, 0);
                            log::info!("New folder IPNS published: {}", ipns_name_clone);
                        }
                        cipherbox_api_client::PublishResult::Conflict { .. } => {
                            // Sequence 0 should never conflict -- log and continue
                            log::warn!("Unexpected conflict on new folder IPNS publish for {}", ipns_name_clone);
                        }
                    }

                    let lock = coordinator.get_lock(&parent_ipns_name);
                    let _guard = lock.lock().await;

                    let parent_json = crate::encrypt_metadata_to_json(
                        &parent_metadata, &parent_folder_key,
                    )?;

                    let seq = coordinator.resolve_sequence(&api, &parent_ipns_name).await?;

                    let parent_meta_cid = cipherbox_api_client::ipfs::upload_content(
                        &api, &parent_json,
                    ).await.map_err(|e| format!("{}", e))?;

                    let parent_key_arr: [u8; 32] = parent_ipns_key.try_into()
                        .map_err(|_| "Invalid parent IPNS key length".to_string())?;
                    let new_seq = seq + 1;
                    let parent_value = format!("/ipfs/{}", parent_meta_cid);
                    let parent_record = cipherbox_core::ipns::create_ipns_record(
                        &parent_key_arr, &parent_value, new_seq, 86_400_000,
                    ).map_err(|e| format!("Parent IPNS record failed: {}", e))?;
                    let parent_marshaled = cipherbox_core::ipns::marshal_ipns_record(
                        &parent_record,
                    ).map_err(|e| format!("Parent IPNS marshal failed: {}", e))?;
                    let parent_record_b64 = base64::engine::general_purpose::STANDARD
                        .encode(&parent_marshaled);

                    // Parent folder publish after mkdir includes conflict detection.
                    // On conflict, signal the FS thread via upload_tx so the debounced
                    // publisher retries with a fresh sequence (D-11a).
                    let parent_req = cipherbox_api_client::IpnsPublishRequest {
                        ipns_name: parent_ipns_name.clone(),
                        record: parent_record_b64,
                        metadata_cid: parent_meta_cid,
                        encrypted_ipns_private_key: None,
                        key_epoch: None,
                        expected_sequence_number: Some(seq.to_string()),
                    };
                    match cipherbox_api_client::ipns::publish_ipns(&api, &parent_req).await.map_err(|e| format!("{}", e))? {
                        cipherbox_api_client::PublishResult::Success => {
                            coordinator.record_publish(&parent_ipns_name, new_seq);
                            // Only unpin old CID on successful publish
                            if let Some(old) = parent_old_cid {
                                let _ = cipherbox_api_client::ipfs::unpin_content(&api, &old).await;
                            }
                            // Remove journal entry now that parent publish is confirmed (D-11b).
                            let _ = journal_for_mkdir.remove(&mkdir_journal_entry_id);
                            log::info!("Parent metadata published after mkdir");
                        }
                        cipherbox_api_client::PublishResult::Conflict { current_sequence_number } => {
                            // Signal the FS thread to re-arm the debounced publisher with a
                            // fresh sequence (D-11a). Journal entry stays until parent publish
                            // confirms (D-11b) — do NOT remove it here.
                            log::warn!(
                                "Conflict on parent mkdir publish (expected seq {}, server has {}). Signalling retry.",
                                seq, current_sequence_number
                            );
                            let _ = upload_tx.send(crate::FsEvent::MkdirConflict { parent_ino });
                        }
                    }
                    Ok::<(), String>(())
                });

                if let Err(e) = result {
                    log::error!("Background mkdir publish failed: {}", e);
                }
            });

            Ok(fuse_attr)
        })();

        match result {
            Ok(fuse_attr) => {
                reply.entry(&DIR_TTL, &fuse_attr, 0);
            }
            Err(e) => {
                log::error!("mkdir failed: {}", e);
                reply.error(libc::EIO);
            }
        }
    }

    /// Remove an empty directory.
    pub fn handle_rmdir(fs: &mut CipherBoxFS, parent: u64, name: &OsStr, reply: ReplyEmpty) {
        let name_str = match name.to_str() {
            Some(n) => n,
            None => {
                reply.error(libc::ENOENT);
                return;
            }
        };

        let child_ino = match fs.inodes.find_child(parent, name_str) {
            Some(ino) => ino,
            None => {
                reply.error(libc::ENOENT);
                return;
            }
        };

        // Capture folder data for bin entry before inode removal
        let bin_entry_data = match fs.inodes.get(child_ino) {
            Some(inode) => {
                match &inode.kind {
                    InodeKind::Folder {
                        ipns_name,
                        encrypted_folder_key,
                        ipns_private_key,
                        ..
                    } => {
                        // Check for non-empty folder (POSIX requirement)
                        if let Some(ref children) = inode.children {
                            if !children.is_empty() {
                                reply.error(libc::ENOTEMPTY);
                                return;
                            }
                        }

                        let now_ms = SystemTime::now()
                            .duration_since(std::time::UNIX_EPOCH)
                            .unwrap_or_default()
                            .as_millis() as u64;
                        let created_ms = inode
                            .attr
                            .crtime
                            .duration_since(std::time::UNIX_EPOCH)
                            .unwrap_or_default()
                            .as_millis() as u64;

                        // Build the ECIES-wrapped IPNS private key for the FolderEntry
                        let ipns_key_encrypted = match ipns_private_key {
                            Some(key) => match cipherbox_crypto::wrap_key(key, &fs.public_key) {
                                Ok(wrapped) => hex::encode(&wrapped),
                                Err(e) => {
                                    log::error!(
                                        "rmdir: failed to wrap IPNS key for bin entry: {}",
                                        e
                                    );
                                    reply.error(libc::EIO);
                                    return;
                                }
                            },
                            None => {
                                log::error!(
                                    "rmdir: missing folder IPNS private key for ino {}",
                                    child_ino
                                );
                                reply.error(libc::EIO);
                                return;
                            }
                        };

                        let folder_entry = cipherbox_core::folder::FolderEntry {
                            id: cipherbox_crypto::utils::generate_uuid_v4(),
                            name: inode.name.clone(),
                            ipns_name: ipns_name.clone(),
                            folder_key_encrypted: encrypted_folder_key.clone(),
                            ipns_private_key_encrypted: ipns_key_encrypted,
                            created_at: if created_ms > 0 { created_ms } else { now_ms },
                            modified_at: now_ms,
                        };

                        Some((inode.name.clone(), folder_entry))
                    }
                    _ => {
                        reply.error(libc::ENOTDIR);
                        return;
                    }
                }
            }
            None => {
                reply.error(libc::ENOENT);
                return;
            }
        };

        log::debug!("rmdir: {} from parent {}", name_str, parent);

        let now = SystemTime::now();

        // Remove from publish queue before removing inode — a queued folder
        // that no longer exists would cause "Folder inode not found" on flush.
        fs.publish_queue.remove(&child_ino);
        fs.inodes.remove(child_ino);

        if let Some(parent_inode) = fs.inodes.get_mut(parent) {
            parent_inode.attr.mtime = now;
            parent_inode.attr.ctime = now;
        }

        if let Err(e) = fs.update_folder_metadata(parent) {
            log::error!("Failed to update folder metadata after rmdir: {}", e);
        }

        // Create bin entry and publish to bin IPNS (fire-and-forget)
        if let Some((item_name, folder_entry)) = bin_entry_data {
            let parent_ipns_name = fs
                .inodes
                .get(parent)
                .map(|p| match &p.kind {
                    InodeKind::Root { ipns_name, .. } => ipns_name.clone().unwrap_or_default(),
                    InodeKind::Folder { ipns_name, .. } => ipns_name.clone(),
                    _ => String::new(),
                })
                .unwrap_or_default();

            if parent_ipns_name.is_empty() {
                log::warn!(
                    "rmdir: missing parent IPNS name for parent ino {}, skipping bin publish",
                    parent
                );
            } else {
                let parent_path = crate::helpers::build_folder_path(fs, parent);

                let bin_entry = cipherbox_core::bin::BinEntry {
                    id: cipherbox_crypto::utils::generate_uuid_v4(),
                    item_type: cipherbox_core::bin::BinItemType::Folder,
                    name: item_name,
                    original_parent_ipns_name: parent_ipns_name,
                    original_path: parent_path,
                    deleted_at: now
                        .duration_since(std::time::UNIX_EPOCH)
                        .unwrap_or_default()
                        .as_millis() as u64,
                    size: 0,
                    mime_type: String::new(),
                    content_cid: None,
                    content_size: None,
                    version_cids: None,
                    file_pointer: None,
                    folder_entry: Some(folder_entry),
                };

                crate::spawn_bin_entry_publish(
                    fs.api.clone(),
                    fs.rt.clone(),
                    bin_entry,
                    fs.private_key.clone(),
                    fs.public_key.to_vec(),
                    fs.publish_coordinator.clone(),
                );
            }
        }

        reply.ok();
    }

    /// Rename or move a file/folder.
    pub fn handle_rename(
        fs: &mut CipherBoxFS,
        parent: u64,
        name: &OsStr,
        newparent: u64,
        newname: &OsStr,
        reply: ReplyEmpty,
    ) {
        log::debug!(
            "rename: {:?} (parent {}) -> {:?} (parent {})",
            name,
            parent,
            newname,
            newparent,
        );
        let name_str = match name.to_str() {
            Some(n) => n,
            None => {
                reply.error(libc::EINVAL);
                return;
            }
        };
        let newname_str = match newname.to_str() {
            Some(n) => n,
            None => {
                reply.error(libc::EINVAL);
                return;
            }
        };

        // Find source inode (with FUSE-T truncated name fallback)
        let (source_ino, actual_name) = match fs.inodes.find_child(parent, name_str) {
            Some(ino) => (ino, name_str.to_string()),
            None => {
                let parent_inode = match fs.inodes.get(parent) {
                    Some(i) => i,
                    None => {
                        reply.error(libc::ENOENT);
                        return;
                    }
                };
                let children = parent_inode.children.clone().unwrap_or_default();
                let mut matches: Vec<(u64, String)> = Vec::new();
                for &child_ino in &children {
                    if let Some(child) = fs.inodes.get(child_ino) {
                        if is_platform_special(&child.name) {
                            continue;
                        }
                        if child.name.ends_with(name_str) && child.name.len() > name_str.len() {
                            matches.push((child_ino, child.name.clone()));
                        }
                    }
                }
                if matches.len() == 1 {
                    log::debug!(
                        "rename suffix-match: truncated {:?} matched full name {:?}",
                        name_str,
                        matches[0].1
                    );
                    (matches[0].0, matches[0].1.clone())
                } else {
                    log::debug!(
                        "rename failed: {:?} not found (suffix matches: {})",
                        name_str,
                        matches.len()
                    );
                    reply.error(libc::ENOENT);
                    return;
                }
            }
        };

        let name_str = &actual_name;

        log::debug!(
            "rename: {} (ino {}) in parent {} -> {} in parent {}",
            name_str,
            source_ino,
            parent,
            newname_str,
            newparent,
        );

        // If destination exists, handle replacement
        if let Some(dest_ino) = fs.inodes.find_child(newparent, newname_str) {
            // Self-replace (rename "a" to "a" in same dir): no-op
            if dest_ino == source_ino {
                reply.ok();
                return;
            }

            if let Some(dest_inode) = fs.inodes.get(dest_ino) {
                // Validate kind compatibility (POSIX: can't replace file with dir or vice versa)
                let source_is_dir = fs
                    .inodes
                    .get(source_ino)
                    .map(|i| matches!(i.kind, InodeKind::Root { .. } | InodeKind::Folder { .. }))
                    .unwrap_or(false);
                let dest_is_dir = matches!(
                    dest_inode.kind,
                    InodeKind::Root { .. } | InodeKind::Folder { .. }
                );
                if source_is_dir && !dest_is_dir {
                    reply.error(libc::ENOTDIR);
                    return;
                }
                if !source_is_dir && dest_is_dir {
                    reply.error(libc::EISDIR);
                    return;
                }

                match &dest_inode.kind {
                    InodeKind::Folder { .. } => {
                        if let Some(ref children) = dest_inode.children {
                            if !children.is_empty() {
                                reply.error(libc::ENOTEMPTY);
                                return;
                            }
                        }
                    }
                    InodeKind::File { cid, .. } => {
                        if !cid.is_empty() {
                            let cid_clone = cid.clone();
                            let api = fs.api.clone();
                            fs.rt.spawn(async move {
                                let _ = cipherbox_api_client::ipfs::unpin_content(&api, &cid_clone)
                                    .await;
                            });
                        }
                    }
                    _ => {}
                }
            }
            fs.publish_queue.remove(&dest_ino);
            fs.inodes.remove(dest_ino);
        }

        // Remove source from old parent's name index (NFC-normalized)
        {
            use unicode_normalization::UnicodeNormalization;
            let nfc_key: String = name_str.nfc().collect();
            fs.inodes.name_to_ino.remove(&(parent, nfc_key));
        }

        // Update the source inode's name and parent
        if let Some(inode) = fs.inodes.get_mut(source_ino) {
            inode.name = newname_str.to_string();
            inode.parent_ino = newparent;
            inode.attr.ctime = SystemTime::now();
        }

        // Update the name lookup index for the new location (NFC-normalized)
        {
            use unicode_normalization::UnicodeNormalization;
            let nfc_key: String = newname_str.nfc().collect();
            fs.inodes
                .name_to_ino
                .insert((newparent, nfc_key), source_ino);
        }

        if parent != newparent {
            if let Some(old_parent) = fs.inodes.get_mut(parent) {
                if let Some(ref mut children) = old_parent.children {
                    children.retain(|&c| c != source_ino);
                }
                old_parent.attr.mtime = SystemTime::now();
                old_parent.attr.ctime = SystemTime::now();
            }
            if let Some(new_parent) = fs.inodes.get_mut(newparent) {
                if let Some(ref mut children) = new_parent.children {
                    children.push(source_ino);
                }
                new_parent.attr.mtime = SystemTime::now();
                new_parent.attr.ctime = SystemTime::now();
            }

            if let Err(e) = fs.update_folder_metadata(parent) {
                log::error!("Failed to update old parent metadata after rename: {}", e);
            }
            if let Err(e) = fs.update_folder_metadata(newparent) {
                log::error!("Failed to update new parent metadata after rename: {}", e);
            }
        } else {
            if let Some(parent_inode) = fs.inodes.get_mut(parent) {
                parent_inode.attr.mtime = SystemTime::now();
                parent_inode.attr.ctime = SystemTime::now();
            }
            if let Err(e) = fs.update_folder_metadata(parent) {
                log::error!("Failed to update parent metadata after rename: {}", e);
            }
        }

        reply.ok();
    }
}

